package com.studenthub.app; import android.app.*; import android.os.*; import android.net.*; import android.webkit.*; import androidx.webkit.WebViewAssetLoader; import androidx.webkit.WebViewClientCompat;
public class WebAppActivity extends Activity{WebView w;ValueCallback<Uri[]> cb;public void onCreate(Bundle b){super.onCreate(b);w=new WebView(this);setContentView(w);WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMediaPlaybackRequiresUserGesture(false);WebViewAssetLoader l=new WebViewAssetLoader.Builder().addPathHandler("/assets/",new WebViewAssetLoader.AssetsPathHandler(this)).build();w.setWebViewClient(new WebViewClientCompat(){public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){return l.shouldInterceptRequest(r.getUrl());}});w.setWebChromeClient(new WebChromeClient(){public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> c,FileChooserParams p){cb=c;try{Intent intent=p.createIntent(); intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true); startActivityForResult(intent,42);return true;}catch(Exception e){cb=null;return false;}}});String p=getIntent().getStringExtra("page");w.loadUrl("https://appassets.androidplatform.net/assets/studenthub/"+(p==null?"index.html":p));}protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==42&&cb!=null){Uri[] x=null;if(c==RESULT_OK&&d!=null){if(d.getClipData()!=null){int n=d.getClipData().getItemCount();x=new Uri[n];for(int i=0;i<n;i++)x[i]=d.getClipData().getItemAt(i).getUri();}else if(d.getData()!=null)x=new Uri[]{d.getData()};}cb.onReceiveValue(x);cb=null;}}public void onBackPressed(){if(w.canGoBack())w.goBack();else super.onBackPressed();}}